  "Cách rút gọn mệnh đề quan hệ": "How to reduce relative clauses",
  "Cách sử dụng 'will' để diễn đạt một quyết định tại thời điểm nói, một dự đoán không có căn cứ hoặc một lời hứa trong bài thi TOEIC.": "How to use 'will' to express a decision made at the moment of speaking, an unsupported prediction, or a promise in the TOEIC test.",
  "Cách sử dụng cấu trúc 'had + V3/ed' để diễn tả một hành động xảy ra và hoàn thành trước một hành động khác hoặc một thời điểm xác định trong quá khứ, thường xuất hiện trong các câu phức với 'before', 'after', 'by the time'.": "How to use 'had + V3/ed' to describe an action that happened and finished before another action or a specific point in the past, often found in complex sentences with 'before', 'after', 'by the time'.",
  "Cách sử dụng cấu trúc 'will have + V3/ed' để diễn tả một hành động sẽ hoàn tất trước một thời điểm hoặc một hành động khác trong tương lai, thường đi kèm với các cụm từ 'by the time' hoặc 'by + mốc thời gian'.": "How to use 'will have + V3/ed' to describe an action that will be completed before a point in time or another action in the future, often with 'by the time' or 'by + time marker'.",
  "Cách sử dụng cấu trúc 'will have been + V-ing' để diễn tả một hành động xảy ra và kéo dài liên tục đến một thời điểm nhất định trong tương lai, thường đi kèm với khoảng thời gian nhấn mạnh tính liên tục.": "How to use 'will have been + V-ing' to describe an action that happens and continues up to a certain point in the future, often with a time span that emphasizes continuity.",
  "Cách sử dụng thì Hiện tại hoàn thành để diễn tả hành động bắt đầu trong quá khứ và kéo dài đến hiện tại, hoặc hành động vừa mới xảy ra và để lại kết quả. Tập trung vào các dấu hiệu nhận biết như 'since', 'for', 'already', 'yet' thường gặp trong bài thi TOEIC.": "How to use the present perfect to describe an action that started in the past and continues to the present, or one that just happened and left a result. Focuses on signals like 'since', 'for', 'already', 'yet' that often appear in the TOEIC test.",
  "Cách sử dụng thì hiện tại tiếp diễn để diễn tả hành động đang xảy ra tại thời điểm nói, các tình huống tạm thời và các dấu hiệu nhận biết thường gặp trong bài thi TOEIC như 'now', 'at the moment', 'currently'.": "How to use the present continuous to describe an action happening at the moment of speaking, temporary situations, and common TOEIC signals such as 'now', 'at the moment', 'currently'.",
  "Cách sử dụng thì Quá khứ đơn để diễn tả các hành động đã kết thúc trong quá khứ, cách chia động từ có quy tắc và bất quy tắc, cùng các dấu hiệu nhận biết phổ biến trong bài thi TOEIC.": "How to use the simple past to describe actions that ended in the past, how to conjugate regular and irregular verbs, and common signal words in the TOEIC test.",
  "Cách sử dụng, cấu trúc và dấu hiệu nhận biết của thì hiện tại hoàn thành tiếp diễn để diễn tả hành động bắt đầu trong quá khứ và kéo dài liên tục đến hiện tại, nhấn mạnh tính quá trình.": "Usage, structure and signals of the present perfect continuous to describe an action that started in the past and continues up to the present, emphasizing the process.",
