  "Câu Nghe, Ngữ pháp và Đọc chọn ngẫu nhiên từ ngân hàng đề. Kết quả ước lượng trình độ hiện tại và chỉ ra phần đang kéo điểm bạn xuống.": "Listening, Grammar and Reading questions are picked at random from the question bank. Your result estimates your current level and shows what's pulling your score down.",
