  "câu trộn Nghe – Đọc – Ngữ pháp, chọn ngẫu nhiên từ ngân hàng đề thi. Kết quả dùng để ước lượng năng lực ban đầu và sinh lộ trình 3 chặng phù hợp.": "mixed Listening – Reading – Grammar questions, randomly picked from the test bank. Results are used to estimate your starting level and generate a suitable 3-stage roadmap.",
  "Cấu trúc": "Structure",
  "Cấu trúc 'will be + V-ing' dùng để diễn tả một hành động đang xảy ra tại một thời điểm xác định trong tương lai hoặc một lịch trình đã được sắp xếp sẵn. Trong bài thi TOEIC, thì này thường xuất hiện trong phần mô tả tranh (Part 1) hoặc các thông báo về sự kiện sắp tới.": "The 'will be + V-ing' structure describes an action in progress at a specific point in the future or an already scheduled plan. In the TOEIC test, this tense often appears in picture descriptions (Part 1) or announcements about upcoming events.",
