  "Đề full 200 câu theo format TOEIC và đề mẫu VSTEP. Audio phát một lần, không tua, tự nộp khi hết giờ.": "Full 200-question tests in TOEIC format plus VSTEP sample tests. Audio plays once with no rewind, and auto-submits when time runs out.",
  "Đề full test 200 câu": "Full 200-question tests",
  "Đề full test 200 câu, có audio, đáp án và lời giải. Đề miễn phí làm được ngay sau khi đăng ký.": "Full 200-question tests with audio, answers and explanations. Free tests are available right after you sign up.",
  "Đề gồm 4 Part nghe và 3 Part đọc. Bài viết đi qua từng Part: số câu, dạng câu hỏi và thời gian nên dành.": "The test has 4 Listening Parts and 3 Reading Parts. This article walks through each Part: number of questions, question types and how much time to spend.",
  "Đề không có câu hỏi ở các Part đã chọn": "The test has no questions in the selected Parts",
  "Đề không có phần đã chọn": "Test does not include the selected section",
  "đề kiểm tra": "quizzes",
  "Đề kiểm tra": "Quiz",
  "Đề kiểm tra ghép từ câu hỏi đã duyệt trong ngân hàng và câu hỏi bạn soạn; câu mới của bạn được duyệt cùng đề.": "Quizzes are built from approved questions in the question bank and questions you write; your new questions are approved along with the quiz.",
  "Để lại câu hỏi và số điện thoại trong khung chat này, đội hỗ trợ sẽ liên hệ lại trong giờ làm việc. Thông tin hotline có ở trang Liên hệ.": "Leave your question and phone number in this chat box and the support team will get back to you during working hours. Hotline details are on the Contact page.",
  "Để lại email để nhận bài mới qua bản tin.": "Leave your email to receive new articles in our newsletter.",
  "Để lại số điện thoại": "Leave your phone number",
