  "Đề mẫu trên OrbiLingo": "Sample tests on OrbiLingo",
  "Đề mới trong kho": "New tests in the library",
  "Đề này dành cho gói VIP": "This test is for the VIP plan",
  "Đề này thuộc kho đề VIP. Nâng cấp để làm full test hoặc luyện từng Part của đề.": "This test is in the VIP test library. Upgrade to take the full test or practice each Part of it.",
  "Để nguyên tất cả và thời gian thi thật là làm full test. Bỏ bớt Part hoặc đổi thời gian để luyện riêng.": "Leave everything as is with the real exam time to take the full test. Remove Parts or change the time to practice separately.",
  "đề nói": "speaking prompts",
