  "Để sau": "Later",
  "Để sổ tay lỗi sai và lịch ôn hoạt động, hệ thống cần lưu bài làm của bạn. Đăng ký mất chưa tới một phút.": "To make the Mistake notebook and review schedule work, the system needs to save your attempts. Signing up takes under a minute.",
  "Đề Speaking học viên ghi âm ở mục Luyện Nói; giáo viên chấm theo tiêu chí.": "Speaking prompts that students record in Speaking practice; teachers grade by criteria.",
