  "Đề thi thử học viên đang làm: thời lượng, cấu trúc Part và quyền truy cập Miễn phí / VIP. Đề mới cần Trưởng bộ môn duyệt trước khi công khai.": "Mock tests students take: duration, Part structure, and Free / VIP access. New tests need Head of Department approval before publishing.",
  "Đề thi thử TOEIC, VSTEP chấm tự động và đề Viết, Nói giáo viên chấm. Cột \"Đã giao\" cho biết đề được các lớp dùng bao nhiêu lần.": "Auto-graded TOEIC and VSTEP mock tests, plus Writing and Speaking tests graded by teachers. The \"Assigned\" column shows how many times classes have used each test.",
  "Đề thi VIP": "VIP tests",
  "Đề TOEIC": "TOEIC tests",
  "Đề TOEIC bám sát format ETS (200 câu, 120 phút, 7 Part) và đề VSTEP theo format Bộ GD&ĐT 4 kỹ năng. Audio chuẩn tốc độ thi thật, không cho tua lùi để mô phỏng điều kiện phòng thi.": "TOEIC tests follow the ETS format closely (200 questions, 120 minutes, 7 Parts) and VSTEP tests follow the Ministry of Education and Training 4-skill format. Audio plays at real test speed with no rewinding, to simulate exam-room conditions.",
  "Đề TOEIC full 200 câu theo format Listening & Reading và đề VSTEP theo định dạng của Bộ GD&ĐT. Làm trên máy như thi thật, nộp bài là có điểm và giải thích.": "Full 200-question TOEIC tests in Listening & Reading format and VSTEP tests in the MOET format. Take them on screen like the real exam, and get your score and explanations on submit.",
  "Đề TOEIC trên OrbiLingo": "TOEIC tests on OrbiLingo",
  "Đề trắc nghiệm · chấm tự động": "Multiple-choice tests · auto-graded",
  "Đề trắc nghiệm (thi thử TOEIC, VSTEP) chấm tự động và đề tự luận (Viết, Nói) nộp về bàn chấm của giáo viên.": "Multiple-choice tests (TOEIC, VSTEP mock tests) are graded automatically; essay tests (Writing, Speaking) are submitted to the teacher's grading desk.",
