  "Hiện có {{toeicTests}} đề TOEIC và {{vstepTests}} đề VSTEP đang mở. Phòng thi thử chạy audio một lần, tính giờ như thi thật, nộp bài xong có giải thích từng câu.": "There are currently {{toeicTests}} TOEIC tests and {{vstepTests}} VSTEP tests available. The mock test room plays the audio once and is timed like the real test; after submitting you get an explanation for every question.",
  "Hiện dưới video cho học viên. Mục: # Ngữ pháp, # Phát âm, # Mẫu câu, # Kỹ năng, # Từ vựng, # Mệnh đề, # Mạo từ (chỉ ghi ngữ pháp thật vào # Ngữ pháp). Các trường cách nhau dấu |. Mạo từ: thụt 2 dấu cách để thêm từ đi kèm (node con).": "Shown below the video for students. Sections: # Grammar, # Pronunciation, # Phrases, # Skills, # Vocabulary, # Clauses, # Articles (only put real grammar under # Grammar). Separate fields with the | character. Articles: indent 2 spaces to add an accompanying word (child node).",
