  "Khách chưa đăng nhập xem được bài này": "Guests who aren't signed in can view this lesson",
  "Khách sạn: nhận phòng, báo sự cố, trả phòng": "Hotel: checking in, reporting problems, checking out",
  "Khách vãng lai có thể xem cấu trúc đề thi, tra bảng quy đổi điểm và tải tài liệu mở. Để làm bài thi thử, lưu lỗi sai và nhận lộ trình, bạn cần đăng ký tài khoản miễn phí (mất chưa đến 1 phút).": "Guests can view the test structure, look up the score conversion table and download free materials. To take mock tests, save mistakes and get a roadmap, you need to sign up for a free account (takes less than 1 minute).",
  "Khi có bài tập mới hoặc sắp tới hạn nộp.": "When a new assignment arrives or is about to be due.",
