  "Mỗi câu có đáp án, được gắn Part và chủ điểm kiến thức (thì, từ loại, mệnh đề...), phần lớn kèm lời giải và bản dịch. Câu mới chỉ được dùng trong đề sau khi trưởng bộ môn duyệt.": "Every question has an answer, is tagged with a Part and a knowledge topic (tense, word form, clause...), and most come with an explanation and translation. New questions are only used in tests after the head of department approves them.",
