  "Nghe · Đọc · Viết · Nói theo Khung năng lực 6 bậc Việt Nam. Chuẩn đầu ra đại học, sau đại học, thi công chức, giáo viên.": "Listening · Reading · Writing · Speaking under Vietnam's 6-level proficiency framework. For university and postgraduate graduation requirements, civil service exams and teachers.",
