  "Nghe bài nói dài": "Listening to a long talk",
  "Nghe câu tiếng Anh và gõ lại chính xác từng từ. Hệ thống so khớp từng từ và chỉ ra chỗ bạn nghe sót.": "Listen to an English sentence and type it exactly, word by word. The system compares each word and shows what you missed.",
  "Nghe chép": "Listen and",
  "Nghe chép chính tả giúp bạn bắt âm cuối, nối âm và từ chức năng — những thứ dễ bị bỏ sót trong Part 2–4.": "Dictation helps you catch final sounds, linking and function words, which are easy to miss in Parts 2–4.",
