  "Nghe thông báo, hội thoại quen thuộc; viết email 120 từ; nói 2–3 phút về đời sống": "Understand familiar announcements and conversations; write a 120-word email; speak for 2–3 minutes about daily life",
  "Nghe thông báo, hướng dẫn ngắn (Part 1), hội thoại (Part 2) và bài giảng, bài nói dài (Part 3) như bài thi thật.": "Listen to announcements, short instructions (Part 1), conversations (Part 2) and lectures, long talks (Part 3) as in the real test.",
