  "Nghe tối đa 3 lần rồi gõ lại. Bạn có thể giảm tốc độ nếu cần.": "Listen up to 3 times, then type it. You can slow down the speed if needed.",
  "Nghe từng âm, từng từ": "Listening to each sound and word",
  "Nghe và Đọc chấm tự động ngay khi nộp. Viết và Nói được giáo viên chấm theo tiêu chí của Bộ GD&ĐT, có nhận xét từng lỗi để biết lần sau sửa gì.": "Listening and Reading are auto-graded as soon as you submit. Writing and Speaking are graded by teachers using the Ministry of Education and Training criteria, with feedback on each mistake so you know what to fix next time.",
