  "OrbiLingo — Trang chủ": "OrbiLingo — Home",
  "OrbiLingo hôm nay": "OrbiLingo today",
  "OrbiLingo khác gì các trang luyện đề thông thường?": "How is OrbiLingo different from ordinary test-practice sites?",
  "OrbiLingo là đồ án chuyên ngành của Khoa CNTT: nền tảng luyện thi TOEIC và VSTEP với thi thử, sổ tay lỗi sai, ôn tập ngắt quãng và lớp học cùng giáo viên.": "OrbiLingo is a major project of the Faculty of IT: a TOEIC and VSTEP prep platform with mock tests, a Mistake notebook, spaced repetition and classes with teachers.",
  "OrbiLingo vận hành theo vòng học tập khép kín 5 bước: chẩn đoán đầu vào → lộ trình cá nhân hoá → luyện tập/thi thử → tự động phân tích lỗi sai → ôn tập ngắt quãng. Mọi câu sai của bạn đều được lưu lại và nhắc ôn đúng thời điểm thay vì làm đề xong rồi quên.": "OrbiLingo runs on a closed 5-step learning loop: initial diagnosis → personalized roadmap → practice/mock tests → automatic mistake analysis → spaced repetition. Every wrong answer you make is saved and brought back for review at the right time, instead of being forgotten once you finish a test.",
  "Ô nhiễm, biến đổi khí hậu, bảo vệ môi trường.": "Pollution, climate change, environmental protection.",
