  "Tình huống văn phòng, họp, thuyết trình, phỏng vấn — đúng bối cảnh hội thoại (Part 3) và bài nói ngắn (Part 4).": "Office situations, meetings, presentations, interviews — matching the settings of conversations (Part 3) and short talks (Part 4).",
