  "Tính theo âm, không theo chữ: chữ nguyên âm nhưng đọc là phụ âm → vẫn dùng a — a university /ˌjuː-/, a European, a one-way ticket": "Based on sound, not spelling: a vowel letter that is pronounced as a consonant → still use a — a university /ˌjuː-/, a European, a one-way ticket",
  "Tính theo âm, không theo chữ: h câm hoặc chữ viết tắt đọc bằng nguyên âm → dùng an — an hour, an honest person, an MBA": "Based on sound, not spelling: a silent h or an abbreviation read with a vowel → use an — an hour, an honest person, an MBA",
