  "Toàn bộ các bộ từ vựng TOEIC trong hệ thống: từ, loại từ, phiên âm, nghĩa và câu ví dụ.": "All TOEIC vocabulary sets in the system: words, parts of speech, pronunciation, meanings and example sentences.",
  "Toàn bộ câu trả lời hiện tại sẽ không được lưu. Bạn chắc chứ?": "All your current answers will not be saved. Are you sure?",
  "Toàn bộ dữ liệu của {v0} sẽ bị xoá và không thể khôi phục.": "All data for {v0} will be deleted and cannot be recovered.",
  "Toàn bộ khoá học viên đang học trên hệ thống. Mở từng khoá để rà thứ tự bài giảng, xem bài như học viên thấy.": "All courses students are taking on the platform. Open each course to review the lecture order and view lessons as students see them.",
  "Toàn bộ lớp đang mở, giáo viên phụ trách, chuyên cần và tiến độ. Mở lớp mới hoặc phân công lại giáo viên khi cần.": "All open classes, assigned teachers, attendance, and progress. Create a new class or reassign teachers when needed.",
  "Toàn bộ lượt giao bài cho học viên": "All exercise assignments to students",
  "Toàn bộ ngữ pháp TOEIC qua video và luyện chuyên sâu Part 5 (hoàn thành câu), Part 6 (hoàn thành đoạn văn).": "All TOEIC grammar through videos, plus in-depth practice for Part 5 (sentence completion) and Part 6 (text completion).",
  "Toàn bộ ngữ pháp từ câu đơn đến nâng cao — nền cho bài Đọc và bài Viết VSTEP.": "All grammar from simple to advanced sentences — the foundation for VSTEP Reading and Writing.",
  "Toàn bộ nội dung VIP đã được mở.": "All VIP content is unlocked.",
  "Toàn hệ thống · dữ liệu học tập thật": "System-wide · real learning data",
  "Toàn màn hình": "Full screen",
  "TOEIC — Part 2 & Part 5 mẫu": "TOEIC — sample Part 2 & Part 5",
  "TOEIC &amp; VSTEP của bạn": "Your TOEIC &amp; VSTEP",
  "TOEIC 120 phút, VSTEP theo từng kỹ năng. Hết giờ tự nộp bài.": "TOEIC 120 minutes, VSTEP by skill. Auto-submits when time is up.",
  "TOEIC đo khả năng dùng tiếng Anh trong môi trường làm việc. Bài thi có hai dạng, phần lớn trường và doanh nghiệp ở Việt Nam yêu cầu dạng Listening & Reading.": "TOEIC measures your ability to use English in the workplace. The test comes in two formats, and most schools and companies in Vietnam require the Listening & Reading format.",
  "TOEIC là gì? Phân biệt TOEIC Listening & Reading và Speaking & Writing": "What is TOEIC? Telling TOEIC Listening & Reading from Speaking & Writing",
  "TOEIC Listening & Reading không đo Viết và Nói, nên nhiều nơi yêu cầu thêm chứng chỉ 4 kỹ năng.": "TOEIC Listening & Reading doesn't measure Writing and Speaking, so many places also require a 4-skill certificate.",
