  "Tra cứu câu hỏi đã xuất bản theo Part để ghép đề và giao bài. Nhập đề từ file Word: hệ thống tự chia câu vào Part 1–7, lưu Nháp để bạn gửi trưởng bộ môn duyệt.": "Browse published questions by Part to build tests and assign work. Import a test from a Word file: the system sorts questions into Parts 1–7 and saves them as Draft for you to submit to the head of department.",
  "Tra cứu, hiệu đính (sửa nội dung, đáp án, giải thích) và lưu trữ câu hỏi thuộc bộ môn; xem trước đúng như học viên làm bài. Nhập đề từ file Word tự chia Part 1–7. Bảng hiển thị tối đa 200 câu theo bộ lọc Part.": "Look up, edit (content, answers, explanations), and archive department questions; preview exactly as students take them. Importing tests from Word files auto-splits Part 1–7. The table shows up to 200 questions per Part filter.",
